// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.ref;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ReferenceDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));

        // Copying a reference copies the HANDLE, not the object.
        Account alias = rajesh;              // both point to the SAME heap object
        log.info(() -> "Same object? " + (rajesh == alias)); // true

        TransferHelper helper = new TransferHelper();
        helper.applyCharge(alias, new BigDecimal("500")); // mutate via alias
        // Change is visible through rajesh because it is the same object.
        log.info(() -> "Rajesh balance after charge via alias: Rs." + rajesh.getBalance());

        // Null reference points to no object.
        Account none = null;
        try {
            none.getBalance();
        } catch (NullPointerException e) {
            log.severe(() -> "NPE: reference 'none' points to no object");
        }

        // Soft reference cache: JVM may reclaim under memory pressure.
        SoftAccountCache cache = new SoftAccountCache();
        cache.put(new Account("CUR3001", "Priya", new BigDecimal("250000")));
        Account cached = cache.get("CUR3001");
        log.info(() -> "Soft-cached account present now? " + (cached != null)
                + (cached != null ? " (" + cached.getHolderName() + ")" : ""));
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in TransferHelper.java ───
class TransferHelper {
    // Receives a COPY of the reference, but it points to the same object.
    void applyCharge(Account account, BigDecimal fee) {
        account.debit(fee); // mutates the shared heap object
    }
}

// ─── Would be in SoftAccountCache.java ───
class SoftAccountCache {
    // Values held via SoftReference → collector may drop them if memory tight.
    private final java.util.Map<String, java.lang.ref.SoftReference<Account>> cache
            = new java.util.HashMap<>();

    void put(Account a) {
        cache.put(a.getAccountId(), new java.lang.ref.SoftReference<>(a));
    }
    Account get(String id) {
        java.lang.ref.SoftReference<Account> ref = cache.get(id);
        return (ref == null) ? null : ref.get(); // get() may return null if reclaimed
    }
}
